package com.estateflow.controller;
import com.estateflow.config.AppContext;import com.estateflow.exception.EstateFlowException;import com.estateflow.model.*;import com.estateflow.model.enums.MaintenancePriority;import com.estateflow.util.*;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.util.StringConverter;import java.time.LocalDate;import java.util.function.Consumer;
public final class WorkOrderFormController extends AbstractDialogController{
 @FXML private ComboBox<Property> propertyBox;@FXML private TextField requestId,title,estimated;@FXML private TextArea scope;@FXML private ComboBox<MaintenancePriority> priority;@FXML private DatePicker dueDate;@FXML private Button saveButton;private WorkOrder existing;private Consumer<Void> saved=x->{};
 public WorkOrderFormController(AppContext c,SceneNavigator n){super(c,n);}
 @FXML private void initialize(){priority.getItems().setAll(MaintenancePriority.values());priority.setValue(MaintenancePriority.MEDIUM);propertyBox.setConverter(new StringConverter<>(){public String toString(Property p){return p==null?"":p.getName()+" — "+p.getCity();}public Property fromString(String s){return null;}});UiTask.run(()->ctx.properties().findAll(),rows->{propertyBox.getItems().setAll(rows);selectExistingProperty();});}
 void init(WorkOrder w,Runnable done){existing=w;saved=x->done.run();if(w!=null){requestId.setText(w.maintenanceRequestId()==null?"":w.maintenanceRequestId().toString());title.setText(w.title());scope.setText(w.scope());priority.setValue(w.priority());dueDate.setValue(w.dueDate());estimated.setText(w.estimatedCost()==null?"":w.estimatedCost().toPlainString());}}
 private void selectExistingProperty(){if(existing!=null)propertyBox.getItems().stream().filter(p->p.getPropertyId().equals(existing.propertyId())).findFirst().ifPresent(propertyBox::setValue);}
 @FXML private void onCancel(){close();}
 @FXML private void onSave(){try{Property p=propertyBox.getValue();Long propertyId=p==null?null:p.getPropertyId();String raw=requestId.getText().trim();Long request=raw.isEmpty()?null:Long.valueOf(raw);String t=title.getText(),sc=InputParser.optionalText(scope.getText());MaintenancePriority pr=priority.getValue();LocalDate due=dueDate.getValue();BigDecimalHolder cost=new BigDecimalHolder(InputParser.optionalMoney("estimatedCost","Estimated cost",estimated.getText()));Long id=existing==null?null:existing.id();WorkOrder w=new WorkOrder(id,propertyId,request,null,null,t,sc,pr,due,existing==null?WorkOrderStatus.DRAFT:existing.status(),cost.value,null,null,null,null,null,null);UiTask.run(()->existing==null?ctx.workOrders().create(w):ctx.workOrders().update(w),saved->{close();this.saved.accept(null);},saveButton);}catch(NumberFormatException e){AlertUtil.info("Work Orders","Maintenance request number must be a whole number.");}catch(EstateFlowException e){ErrorHandler.handle(e);}}
 private record BigDecimalHolder(java.math.BigDecimal value){}
}
